package com.cdac.cssip.meeting.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity @Table(name="online_meetings")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class OnlineMeeting{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private Long staffId;@Column(nullable=false)private Long branchId;@Column(nullable=false,length=160)private String title;@Column(length=1200)private String agenda;@Column(nullable=false)private String platform;@Column(nullable=false,length=1000)private String meetingLink;@Column(nullable=false)private LocalDateTime scheduledAt;@Column(nullable=false)private Integer durationMinutes;@Column(nullable=false)private String status;@Column(length=500)private String cancellationReason;private LocalDateTime createdAt;private LocalDateTime updatedAt;@PrePersist void p(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status="SCHEDULED";}@PreUpdate void u(){updatedAt=LocalDateTime.now();}}
